WITH ValidAccounts AS (SELECT *, ROUND(balance, 0) AS balance_rounded FROM accounts WHERE NOT (status = 'CLOSED' AND opened_date <= '2024-12-23')), AccountsStats AS (SELECT MONTH(opened_date) AS opened_month, CASE WHEN account_type IN ('CHECKING', 'SAVINGS') THEN 'core' ELSE 'other' END AS account_type_group, MIN(balance_rounded) AS min_balance_rounded, ROUND(STDDEV(balance), 2) AS stddev_balance FROM ValidAccounts GROUP BY MONTH(opened_date), CASE WHEN account_type IN ('CHECKING', 'SAVINGS') THEN 'core' ELSE 'other' END) SELECT * FROM AccountsStats;
